const b = $input.first().json.body;
const today = b.data || new Date().toISOString().slice(0, 10);
const wName = (b.workout || 'Treino').trim();
const isBoxe = /box|ilia/i.test(wName);

const treinoFm = [
  'tipo: treino', 'status: feito', `data: ${today}`,
  `modalidade: ${isBoxe ? 'boxe' : 'musculacao'}`,
  `coach: ${isBoxe ? 'ilia' : 'cariani'}`,
  `volume_kg: ${Number(b.volume) || 0}`,
  'rpe: 0', 'duracao_min: 0',
  'area: pessoal', 'fonte: apex',
  `criado: ${today}`, `atualizado: ${today}`,
  'tags:\n  - tema/saude',
].join('\n');

const nutricaoFm = [
  'tipo: nutricao', 'status: parcial', `data: ${today}`,
  `refeicoes: ${Number(b.refeicoes) || 0}`,
  'kcal: 0', 'proteina_g: 0', 'carbo_g: 0', 'gordura_g: 0', 'agua_l: 0', 'aderencia: 0',
  'area: pessoal', 'fonte: apex',
  `criado: ${today}`, `atualizado: ${today}`,
  'tags:\n  - tema/saude',
].join('\n');

const corporalFm = [
  'tipo: corporal', `data: ${today}`,
  `peso_kg: ${Number(b.peso) || 0}`,
  `readiness: ${Number(b.readiness) || 0}`,
  'gordura_pct: 0', 'sono_h: 0', 'fadiga: 0',
  'area: pessoal', 'fonte: apex',
  `criado: ${today}`, `atualizado: ${today}`,
  'tags:\n  - tema/saude',
].join('\n');

return [
  {
    json: {
      fileName: `${today} ${wName}.md`,
      parentId: 'PREENCHER_ID_ONEDRIVE_TREINOS',
      fileContent: `---\n${treinoFm}\n---\n\n# 🥋 ${today} ${wName}\nDia ${b.dia || '?'} · ${b.exercicios || 0} ex · ${b.series || 0} séries · ${b.volume || 0} kg · Streak ${b.streak || 0}d · XP ${b.xp || 0}${b.destaque ? '\n\n**Destaque:** ' + b.destaque : ''}\n`,
    }
  },
  {
    json: {
      fileName: `${today} Nutricao.md`,
      parentId: 'PREENCHER_ID_ONEDRIVE_NUTRICAO',
      fileContent: `---\n${nutricaoFm}\n---\n\n# 🍽️ ${today} Nutricao\n> Projeção APEX. Macros indisponíveis — preencher via Sanji.\n\nRefeições: ${b.refeicoes || 0}\n`,
    }
  },
  {
    json: {
      fileName: `${today} Corporal.md`,
      parentId: 'PREENCHER_ID_ONEDRIVE_CORPORAL',
      fileContent: `---\n${corporalFm}\n---\n\n# 🩺 ${today} Corporal\nPeso: ${b.peso || 0} kg · Readiness: ${b.readiness || 0}%\n`,
    }
  },
];
